// A shared literal field turns the union into a discriminated union
type Result =
  | { ok: true; value: number }
  | { ok: false; error: string };

function unwrap(result: Result): number {
  if (result.ok) {
    return result.value; // narrowed to the success branch
  }
  throw new Error(result.error); // narrowed to the failure branch
}

// A function call keeps the union wide, so both branches stay reachable
function check(flag: boolean): Result {
  return flag ? { ok: true, value: 42 } : { ok: false, error: "timeout" };
}

const result = check(true);
console.log(unwrap(result));
console.log(result.ok ? result.value : result.error);

