class Account {
  static readonly currency = "BRL";
  readonly id: number;
  #balance = 0; // truly private, enforced at runtime
  protected owner: string;

  constructor(id: number, owner: string) {
    this.id = id;
    this.owner = owner;
  }

  deposit(amount: number): number {
    if (amount <= 0) throw new RangeError("amount must be positive");
    this.#balance += amount;
    return this.#balance;
  }

  get balance(): number {
    return this.#balance;
  }
}

