type User = { id: number; name: string };

async function fetchUser(id: number): Promise<User> {
  const response = await fetch(`https://api.example.com/users/${id}`);
  if (!response.ok) {
    throw new Error(`request failed with ${response.status}`);
  }
  return (await response.json()) as User;
}

async function main(): Promise<void> {
  try {
    const user = await fetchUser(7);
    console.log(user.name);
  } catch (error: unknown) {
    // A caught value is unknown until it is checked
    const message = error instanceof Error ? error.message : String(error);
    console.error(message);
  }
}

void main();

type Post = { id: number; title: string };

async function loadPost(id: number): Promise<Post> {
  const response = await fetch(`/api/posts/${id}`);
  return (await response.json()) as Post;
}

async function loadAll(ids: number[]): Promise<Post[]> {
  // Promise.all keeps the element type instead of widening to unknown
  return Promise.all(ids.map((id) => loadPost(id)));
}

loadAll([1, 2, 3]).then((posts) => console.log(posts.map((post) => post.title)));

async function* countdown(from: number): AsyncGenerator<number> {
  for (let i = from; i > 0; i--) {
    yield i;
  }
}

async function run(): Promise<void> {
  for await (const value of countdown(3)) {
    console.log(value);
  }
}

void run();

// Method decorator: wrap the original method while keeping its types
function logged<This, Args extends unknown[], Return>(
  method: (this: This, ...args: Args) => Return,
  context: ClassMethodDecoratorContext<This, (this: This, ...args: Args) => Return>,
): (this: This, ...args: Args) => Return {
  const name = String(context.name);
  return function (this: This, ...args: Args): Return {
    console.log(`calling ${name} with ${args.length} argument(s)`);
    return method.call(this, ...args);
  };
}

class Cart {
  #items: string[] = [];

  @logged
  add(item: string): number {
    this.#items.push(item);
    return this.#items.length;
  }
}

const cart = new Cart();
console.log(cart.add("book"));

const registered: string[] = [];

// Class decorator: receives the class itself and a context object
function register<Class extends abstract new (...args: any[]) => object>(
  value: Class,
  context: ClassDecoratorContext<Class>,
): void {
  registered.push(String(context.name));
}

@register
class Invoice {
  constructor(readonly total: number) {}
}

